pygments.cmdline._print_list_as_json:
def _print_list_as_json(requested_items):
    import json
    result = {}
    if 'lexer' in requested_items:
        info = {}
        for (fullname, names, filenames, mimetypes) in get_all_lexers():
            info[fullname] = {'aliases': names, 'filenames': filenames, 'mimetypes': mimetypes}
        result['lexers'] = info
    if 'formatter' in requested_items:
        info = {}
        for cls in get_all_formatters():
            doc = docstring_headline(cls)
            info[cls.name] = {'aliases': cls.aliases, 'filenames': cls.filenames, 'doc': doc}
        result['formatters'] = info
    if 'filter' in requested_items:
        info = {}
        for name in get_all_filters():
            cls = find_filter_class(name)
            info[name] = {'doc': docstring_headline(cls)}
        result['filters'] = info
    if 'style' in requested_items:
        info = {}
        for name in get_all_styles():
            cls = get_style_by_name(name)
            info[name] = {'doc': docstring_headline(cls)}
        result['styles'] = info
    json.dump(result, sys.stdout)

pygments.styles.__init__.get_all_styles:
def get_all_styles():
    """Return a generator for all styles by name, both builtin and plugin."""
    for v in STYLES.values():
        yield v[1]
    for (name, _) in find_plugin_styles():
        yield name

pygments.lexers.__init__.get_all_lexers:
def get_all_lexers(plugins=True):
    """Return a generator of tuples in the form ``(name, aliases,
    filenames, mimetypes)`` of all know lexers.

    If *plugins* is true (the default), plugin lexers supplied by entrypoints
    are also returned.  Otherwise, only builtin ones are considered.
    """
    for item in LEXERS.values():
        yield item[1:]
    if plugins:
        for lexer in find_plugin_lexers():
            yield (lexer.name, lexer.aliases, lexer.filenames, lexer.mimetypes)

pygments.__init__.lex:
def lex(code, lexer):
    """
    Lex `code` with the `lexer` (must be a `Lexer` instance)
    and return an iterable of tokens. Currently, this only calls
    `lexer.get_tokens()`.
    """
    try:
        return lexer.get_tokens(code)
    except TypeError:
        from pygments.lexer import RegexLexer
        if (isinstance(lexer, type) and issubclass(lexer, RegexLexer)):
            raise TypeError('lex() argument must be a lexer instance, not a class')
        raise

pygments.lexers._lua_builtins.run:
def run():
    version = get_newest_version()
    functions = set()
    for v in ('5.2', version):
        print(f'> Downloading function index for Lua {v}')
        f = get_lua_functions(v)
        print('> %d functions found, %d new:' % (len(f), len(set(f) - functions)))
        functions |= set(f)
    functions = sorted(functions)
    modules = {}
    for full_function_name in functions:
        print(f'>> {full_function_name}')
        m = get_function_module(full_function_name)
        modules.setdefault(m, []).append(full_function_name)
    modules = {k: tuple(v) for (k, v) in modules.items()}
    regenerate(__file__, modules)
